def run(_context):
    tools = mb.list_library_tools(contains='TIW')
    # Filter for flat endmills useful for pocket roughing/finishing
    print('=== FLAT ENDMILLS ===')
    for t in tools:
        desc = t['description'].lower()
        if 'flat' in desc or 'square' in desc:
            print(f"idx={t['index']:2d}  dia={t['diameter_mm']:6.3f}mm  fl={t['flute_length_mm']:5.1f}mm  flutes={t['flutes']}  {t['description']}")
